```javascript
function binarySearch(arr, x) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);

    if (arr[mid] === x) {
      return mid; // found it!
    } else if (arr[mid] < x) { // search right half of array
      left = mid + 1;
    } else { // search left half of array
      right = mid - 1;
    }
  }

  return -1; // not found
}

